//! Independent18-profile captured-pair, timing, membership and reward matrix.
use gielinor_world::{assembly::{Recipe,PreciseRecipe},held_use::{Handler,Scope,Type,Request},inventory::{Inventory,Item},simulation::{World,PlayerData,WorldEvent},stats::Stats,npc::RandomSource,CoordGrid};
struct NoDraw;impl RandomSource for NoDraw{fn below(&mut self,_:u32)->u32{panic!("deterministic pair assembly drew RNG")}}
fn profile(i:usize)->PreciseRecipe{let(raw,out,level,xp,member,first,seq,spot)=if i<11{let(raw,out)=[(1673,1692),(1675,1694),(1677,1696),(1679,1698),(1681,1700),(1683,1702),(6579,6581),(19501,19541),(21099,21108),(21102,21111),(21105,21114)][i];(raw,out,1,40,i>=5,1759,None,None)}else if i<14{let(raw,out,level,member)=[(1714,1716,1,false),(1720,1722,1,true),(10134,10132,37,true)][i-11];(raw,out,level,40,member,1759,None,None)}else{let(raw,out,level,xp,spot)=[(571,1395,54,1000,1370),(575,1399,58,1125,1371),(569,1393,62,1250,1372),(573,1397,66,1375,306)][i-14];(raw,out,level,xp,true,1391,Some(7531),Some(spot))};PreciseRecipe{recipe:Recipe{first,second:raw,output:out,skill:12,level,base_xp:if i<14{4}else{0},members:member},xp_tenths:xp,ticks:if i<14{1}else{3},animation:seq,spot}}
fn credit(inv:&mut Inventory,first:usize,second:usize,out:i32){inv.restore_slot(first,None).unwrap();inv.restore_slot(second,None).unwrap();let free=(0..28).find(|&s|inv.get(s).is_none()).unwrap();inv.restore_slot(free,Some(Item{id:out,count:1,vars:0})).unwrap();}
fn fixture(r:PreciseRecipe,reverse:bool)->(World,gielinor_world::simulation::ActorId,gielinor_world::assembly_production::Request){let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_base(12,99);stats.set_current(12,99);stats.set_fine_xp(12,130344311).unwrap();let mut w=World::default();w.collision.allocate(3200,3200,0);let mut d=PlayerData::new(1,"Independent pair late policy".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);d.xp_rate_hundreds=125;for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:if s==27{995}else{1931},count:if s==27{1000}else{1},vars:0})).unwrap();}for s in[19,3,11]{d.inventory.restore_slot(s,Some(Item{id:r.recipe.first,count:1,vars:0})).unwrap();}for s in[17,8,22]{d.inventory.restore_slot(s,Some(Item{id:r.recipe.second,count:1,vars:0})).unwrap();}w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,true).unwrap();for id in[r.recipe.first,r.recipe.second]{w.held_use_types.insert(id,Type{id,content:-1});}w.held_use_handlers.register(Scope::Types,r.recipe.first,r.recipe.second,Handler::AssemblyProduction{recipe:r,cycle_ticks:2}).unwrap();let h=if reverse{Request{selected_slot:17,selected_id:r.recipe.second,target_slot:19,target_id:r.recipe.first}}else{Request{selected_slot:19,selected_id:r.recipe.first,target_slot:17,target_id:r.recipe.second}};w.prepare_held_use(a,h).unwrap();w.finish_held_use(a,h).unwrap();let q=w.take_assembly_production_request(a).unwrap().unwrap();w.drain_events();(w,a,q)}
#[test]fn seventy_two_life_refusals_before_first_production_credit(){let mut cases=0;for i in 0..18{let r=profile(i);for reverse in[false,true]{for queued in[false,true]{let(mut w,a,q)=fixture(r,reverse);if queued{w.queue_hit(gielinor_world::hits::Target::Player(a),gielinor_world::hits::Hit{display:None,source:None,style:gielinor_world::hits::Style::Typeless,damage:20},1).unwrap();w.tick_with_random(&mut NoDraw).unwrap();assert_eq!(w.data(a).unwrap().stats.current(3),0);assert!(w.drain_events().iter().any(|e|matches!(e,WorldEvent::DeathRequested(_))));w.data_mut(a).unwrap().stats.set_current(3,10);}else{w.data_mut(a).unwrap().stats.set_current(3,0);}let before=w.data(a).unwrap().clone();let _=w.start_assembly_production(a,q,0,3);for _ in 0..12{w.tick_with_random(&mut NoDraw).unwrap();}assert_eq!(w.data(a).unwrap().inventory,before.inventory,"profile{i} reverse{reverse} queued{queued}");assert_eq!(w.data(a).unwrap().stats,before.stats);assert!(!w.drain_events().iter().any(|e|matches!(e,WorldEvent::AssemblyMade{..}|WorldEvent::SkillAdvanced{..})));cases+=1;}}}assert_eq!(cases,72);}
